export type V3 = [number, number, number];
export type Cam = { pos: V3; alvo: V3; fov: number; rolar?: number };
export type Plano = (u: number, d: number) => Cam;
export type Entrada = 'corte' | 'continua' | 'chicote' | 'mergulho' | 'giro';
export type CenaCam = { inicio: number; fim: number; plano: Plano; entrada?: Entrada; tremor?: number; piso?: number };
export const lim: (x: number) => number;
export const suave: (x: number) => number;
export const arranca: (x: number) => number;
export const acelera: (x: number) => number;
export const mix: (a: number, b: number, p: number) => number;
export const mix3: (a: V3, b: V3, p: number) => V3;
export const ruido: (t: number, s?: number) => number;
export function trilho(pontos: { em: number; pos: V3; alvo: V3; fov?: number }[], curva?: (x: number) => number): Plano;
export function orbita(o: { centro?: V3; raio?: number; altura?: number; de?: number; ate?: number; fov?: number; curva?: (x: number) => number }): Plano;
export function aproxima(o: { de: V3; ate: V3; alvo: V3; fovDe?: number; fovAte?: number; curva?: (x: number) => number }): Plano;
export function comPiso(plano: Plano, forca?: number): Plano;
export function comRespiro(c: Cam, t: number, respiro?: number, tremor?: number): Cam;
export type Perfil = 'padrao' | 'calmo';
export const PERFIS: Record<Perfil, { piso: number; respiro: number; entrada: Entrada }>;
export const METAS: Record<Perfil, { primeiroCorte: number | null; maxSemNovidade: number; paradoPct: number | null }>;
export function sequencia(cenas: CenaCam[], o?: { respiro?: number; perfil?: Perfil }): (t: number) => Cam;
export function aplicar<T>(cam3: T, c: Cam): T;
export function medirCamera(camera: (t: number) => Cam, dur: number, fps?: number): { paradoPct: number; movimentoMedio: number; trechosParados: { de: number; ate: number }[] };
export function conferirRitmo(o: { cenas: { inicio: number; fim: number }[]; camera?: (t: number) => Cam; dur: number; eventos?: number[]; fps?: number; perfil?: Perfil; metas?: Partial<{ primeiroCorte: number | null; maxSemNovidade: number; paradoPct: number | null }> }): { ok: boolean; avisos: string[]; medidas: ReturnType<typeof medirCamera> | null; cortes: number[] };
export const CLIMAS: Record<string, any>;
export function prepararRenderizador<T>(THREE: any, renderer: T, exposicao?: number, sombra?: boolean): T;
export function montarLuz(THREE: any, cena: any, clima?: string | object, o?: { alcance?: number; alvo?: V3; mapa?: number }): { principal: any; preenche: any; recorte: any; grupo: any; mirar: (a: V3) => void; pulso: (segDesdeImpacto: number, forca?: number) => void };
export function comSombra<T>(obj: T, faz?: boolean, recebe?: boolean): T;
export function volumeTrilha(impactos: { em: number; silencio?: number; volta?: number }[], base?: number): (t: number) => number;
export function conferirSom(impactos: { em: number; silencio?: number }[], falas?: { de: number; ate: number }[]): string[];
export const quadro: (seg: number, fps?: number) => number;
